contract InvMutTest {
    C c;
    uint256 vaultUtil;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 util) public {
        require(util > 0, "need positive utilization");
        vaultUtil = util;
        uint256 r = c.rate(address(this), address(0x1)); if (__ESBMC_reverted()) return;
        assert(r == 0);
    }

    fallback(bytes calldata) external payable returns (bytes memory) {
        // Both currentUtilizationIndex(address) and utilization(address) return uint256,
        // so one generic answer suffices for this vault stub.
        return abi.encode(vaultUtil);
    }

    receive() external payable {}
}

